parameters.cypher_query:
MATCH (k:King)-[r:ATTACKER_KING|DEFENDER_KING]->(b:Battle)
RETURN gds.graph.project(
  $graph_name,
  k,
  b,
  {
    sourceNodeLabels: labels(k),
    targetNodeLabels: labels(b),
    relationshipType: type(r)
  },
  { undirectedRelationshipTypes: ['ATTACKER_KING','DEFENDER_KING'] }
)

