  $graph_name,
  p,
  b,
  {
    sourceNodeLabels: labels(p),
    targetNodeLabels: labels(b),
    sourceNodeProperties: {},
    targetNodeProperties: {},
    relationshipType: type(r),
    relationshipProperties: {}
  },
